21	  const corsHeaders = {
22	    "Access-Control-Allow-Origin": getCorsOrigin(req),
23	    "Access-Control-Allow-Headers":
24	      "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
