39	    if (claimsError || !claimsData?.claims) throw new Error("Unauthorized");
40	
41	    // No credit deduction — generation is free
42	
43	    const body = await req.json();
44	    const {
45	      job_title,
46	      company_name,
47	      key_responsibilities,
48	      requirements,
49	      nice_to_haves,
50	      employment_type,
51	      location,
52	      salary_range,
