68	
69	GENERATION GUIDELINES:
70	- Structure the JD with clear sections: About the Role, Key Responsibilities, Requirements, Nice-to-Have, What We Offer
71	- Use inclusive, bias-free language
72	- Ensure ATS-friendliness: standard section headers, bullet points, spell out acronyms on first use
73	- ${toneInstruction}
74	- Keep the About the Role section to 2-4 sentences that capture the essence and impact of the position
75	- Key Responsibilities: 5-8 clear bullet points using action verbs
76	- Requirements: 5-8 must-have qualifications, specific and measurable
77	- Nice-to-Have: 3-5 bonus qualifications
78	- What We Offer: 4-6 benefits/perks bullets (use generic competitive offerings if none provided)
79	- If company_name, location, employment_type, or salary_range are provided, incorporate them naturally
80	
81	Return ONLY valid JSON with this exact structure:
82	{
83	  "job_description": "the complete formatted job description as a single string with \\n for line breaks",
84	  "sections": {
85	    "about": "...",
86	    "responsibilities": "...",
87	    "requirements": "...",
88	    "nice_to_haves": "...",
89	    "benefits": "..."
90	  }
91	}`;
92	
93	    const userMessage = [
94	      `Job Title: ${job_title.trim()}`,
95	      company_name ? `Company: ${company_name.trim()}` : null,
96	      employment_type ? `Employment Type: ${employment_type}` : null,
97	      location ? `Location: ${location.trim()}` : null,
98	      salary_range ? `Salary Range: ${salary_range.trim()}` : null,
99	      `\nKey Responsibilities:\n${key_responsibilities.trim()}`,
100	      `\nRequirements:\n${requirements.trim()}`,
101	      nice_to_haves ? `\nNice-to-Have:\n${nice_to_haves.trim()}` : null,
102	    ]
103	      .filter(Boolean)
104	      .join("\n");
105	
106	    const response = await fetch("https://api.openai.com/v1/chat/completions", {
107	      method: "POST",
108	      headers: {
109	        Authorization: `Bearer ${OPENAI_API_KEY}`,
110	        "Content-Type": "application/json",
111	      },
112	      body: JSON.stringify({
113	        model: "gpt-4o",
114	        messages: [
115	          { role: "system", content: systemPrompt },
116	          { role: "user", content: userMessage },
117	        ],
118	        response_format: { type: "json_object" },
119	        temperature: 0.4,
120	      }),
121	    });
122	
123	    if (!response.ok) {
124	      const errBody = await response.text();
125	      throw new Error(`OpenAI API error ${response.status}: ${errBody.slice(0, 200)}`);
126	    }
127	
128	    const aiData = await response.json();
129	    const content = aiData.choices?.[0]?.message?.content;
130	    if (!content) throw new Error("OpenAI returned empty response");
131	
132	    const parsed = JSON.parse(content);
133	
134	    if (!parsed.job_description || !parsed.sections) {
135	      throw new Error("Unexpected response structure from OpenAI");
136	    }
137	
138	    console.log(`generate-jd complete for job_title: ${job_title}`);
139	
140	    return new Response(
141	      JSON.stringify({
142	        success: true,
143	        job_description: parsed.job_description,
144	        sections: parsed.sections,
145	      }),
146	      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
