148	  } catch (err) {
149	    console.error("generate-jd error:", err);
150	    return new Response(
151	      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
152	      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
153	    );
154	  }
155	});
