58	    }
59	
60	    // ── Fetch job info ────────────────────────────────────────
61	    const { data: job, error: jobError } = await supabase
62	      .from("jobs")
63	      .select("id, title, location, department")
64	      .eq("id", link.job_id)
65	      .single();
66	
67	    if (jobError || !job) {
68	      return errorResponse("Job not found", 404);
69	    }
70	
71	    // ── Fetch scored resumes (no PII — no email/phone) ───────
72	    const { data: resumes, error: resumeError } = await supabase
73	      .from("resumes")
74	      .select("id, candidate_name, status")
75	      .eq("job_id", link.job_id)
76	      .eq("status", "done");
77	
78	    if (resumeError) {
79	      console.error("guest-portal: resume fetch error:", resumeError.message);
80	    }
81	
82	    const resumeList = resumes ?? [];
83	    const resumeIds = resumeList.map((r: Record<string, unknown>) => r.id as string);
84	
85	    // ── Fetch scores ─────────────────────────────────────────
86	    const { data: results } = resumeIds.length > 0
87	      ? await supabase
88	          .from("results")
89	          .select("resume_id, overall_score, explanation_json")
90	          .in("resume_id", resumeIds)
91	      : { data: [] };
92	
93	    // ── Fetch candidate stages ────────────────────────────────
94	    const { data: stages } = resumeIds.length > 0
95	      ? await supabase
96	          .from("candidate_stages")
97	          .select("resume_id, stage")
98	          .in("resume_id", resumeIds)
99	      : { data: [] };
100	
101	    // ── Merge and sanitize (NO email, NO phone, NO file paths) ─
102	    const resultsMap = Object.fromEntries(
103	      (results ?? []).map((r: Record<string, unknown>) => [r.resume_id, r])
104	    );
105	    const stagesMap = Object.fromEntries(
106	      (stages ?? []).map((s: Record<string, unknown>) => [s.resume_id, s.stage])
107	    );
108	
109	    const candidates = resumeList
110	      .map((r: Record<string, unknown>) => {
111	        const rid = r.id as string;
112	        const result = resultsMap[rid] as Record<string, unknown> | undefined;
113	        const explanationJson = result?.explanation_json as Record<string, unknown> | null | undefined;
114	        return {
115	          name: (r.candidate_name as string | null) ?? "Unknown",
116	          score: (result?.overall_score as number | null) ?? null,
117	          stage: (stagesMap[rid] as string | null) ?? "new",
118	          summary: (explanationJson?.summary as string | null) ?? null,
119	        };
120	      })
121	      .sort((a, b) => (b.score ?? 0) - (a.score ?? 0));
122	
123	    return new Response(
124	      JSON.stringify({
125	        job: {
126	          title: job.title,
127	          location: (job as Record<string, unknown>).location ?? null,
128	          department: (job as Record<string, unknown>).department ?? null,
129	        },
130	        candidates,
131	        link_label: link.label ?? null,
132	      }),
133	      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
134	    );
135	  } catch (err: unknown) {
136	    const message = err instanceof Error ? err.message : "Internal server error";
137	    console.error("guest-portal error:", message);
138	    return new Response(
139	      JSON.stringify({ error: "Internal server error" }),
140	      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
141	    );
142	  }
143	});
